/// SSRS report.
[
    DataContractAttribute,
    SysOperationContractProcessingAttribute(classStr(METTransferOrderLoadPlanningAidUIBuilder))
]
class METTransferOrderLoadPlanningAidContract
{
    SalesShippingDateConfirmed confirmedShipDateFrom;
    SalesShippingDateRequested confirmedShipDateTo;
    METRoute                   routeID;
    InventLocationId           inventLocationTo;
    InventLocationId           inventLocationFrom;
    boolean                    usePrintManagement;

}

